// Canvas campus map: drawing, pan/zoom/pinch, landmark pins, sample complaint markers, GPS.
// Moved verbatim from the original index.html page script (React migration); only imports/exports were added.
import { escapeHtml } from './analyzer.js';
import { CAMPUS_LOCATION_COORDS, getComplaints } from './demoData.js';
import { setReportPlace } from './reportForm';
import { openTrackerWithId } from './tracker';

/* ══════════ DIBRUGARH UNIVERSITY CAMPUS MAP LOGIC ══════════ */
var DIBRUGARH_UNIVERSITY_CENTER = { lat: 27.4508, lng: 94.8926 };

// CAMPUS_LOCATION_COORDS lives in demoData.js (also used by the officials' map page)


// ════════════ DIBRUGARH UNIVERSITY VECTOR MAP ENGINE (MAP KIT - HIGH PERFORMANCE) ════════════
var currentDraftCoords = { lat: 27.4526, lng: 94.8904 };
var currentDraftLocationLabel = 'Padmanath Gohain Baruah Chatra Nivas (Hostel 1)';
var D = null;
var mapCanvas = null;
var mapCtx = null;
var baseCanvas = null;
var baseCtx = null;
var baseDirty = true;
var mapW = 800, mapH = 400, mapDpr = Math.min(window.devicePixelRatio || 1, 2);
var mapCx = 1570, mapCy = 1178, mapZ = 0.25, mapMinZ = 0.1, mapMaxZ = 8.0;
var targetCx = 1570, targetCy = 1178, targetZ = 0.25;
var mapDirty = true;
var mapShowLabels = true;
var mapCampusBounds = [0, 0, 3141, 2357];
var mapBoundaryPath = null;
var mapBufferPath = null;
var mapPointers = new Map();
var mapMoved = 0;
var mapLastMove = 0;
var mapVelocity = [0, 0];
var mapPinchState = null;
var mapRadarPhase = 0;
var mapActiveComplaintHits = [];
var mapPlaceHits = [];
var campusMapInstance = null;
var isMapInViewport = false;
var mapRafId = null;

var treeImg = new Image();
treeImg.onload = function() {
  baseDirty = true;
  mapDirty = true;
};
treeImg.src = 'data:image/png;base64,';

function bounds(g) {
  var b = [Infinity, Infinity, -Infinity, -Infinity];
  function walk(v) {
    if (typeof v[0] === 'number') {
      b[0] = Math.min(b[0], v[0]); b[1] = Math.min(b[1], v[1]);
      b[2] = Math.max(b[2], v[0]); b[3] = Math.max(b[3], v[1]);
    } else v.forEach(walk);
  }
  if (g.type === 'GeometryCollection') {
    g.geometries.forEach(function(x) {
      var a = bounds(x);
      b = [Math.min(b[0], a[0]), Math.min(b[1], a[1]), Math.max(b[2], a[2]), Math.max(b[3], a[3])];
    });
  } else {
    walk(g.coordinates);
  }
  return b;
}

function makePath(g) {
  if (typeof Path2D === 'undefined') return null;
  var p = new Path2D();
  function line(c, close) {
    if (!c || !c.length) return;
    p.moveTo(c[0][0], c[0][1]);
    for (var i = 1; i < c.length; i++) p.lineTo(c[i][0], c[i][1]);
    if (close) p.closePath();
  }
  function add(o) {
    if (o.type === 'Polygon') o.coordinates.forEach(function(c) { line(c, true); });
    else if (o.type === 'MultiPolygon') o.coordinates.forEach(function(v) { v.forEach(function(c) { line(c, true); }); });
    else if (o.type === 'LineString') line(o.coordinates, false);
    else if (o.type === 'MultiLineString') o.coordinates.forEach(function(c) { line(c, false); });
    else if (o.type === 'GeometryCollection') o.geometries.forEach(add);
  }
  add(g);
  return p;
}

function mapScreen(x, y) {
  return [(x - mapCx) * mapZ + mapW / 2, (y - mapCy) * mapZ + mapH / 2];
}

function mapWorld(sx, sy) {
  return [(sx - mapW / 2) / mapZ + mapCx, (sy - mapH / 2) / mapZ + mapCy];
}

function isBBoxVisible(b) {
  var halfW = mapW / (2 * mapZ) + 30;
  var halfH = mapH / (2 * mapZ) + 30;
  return b[2] >= mapCx - halfW && b[0] <= mapCx + halfW && b[3] >= mapCy - halfH && b[1] <= mapCy + halfH;
}

export function initCampusMap() {
  mapCanvas = document.getElementById('campusMapCanvas');
  if (!mapCanvas) return;
  mapCtx = mapCanvas.getContext('2d', { alpha: false });

  baseCanvas = document.createElement('canvas');
  baseCtx = baseCanvas.getContext('2d', { alpha: false });

  // The map data (2.2 MB) is fetched only once the map nears the viewport, not on every page load
  var load = function() {
    fetch('/Dibrugarh-University-Map-Kit/map-data.json')
      .then(function(r) { return r.json(); })
      .then(function(data) { setupMapWithData(data); })
      .catch(function(err) { console.warn('Could not load campus map data:', err); });
  };
  if (typeof IntersectionObserver === 'undefined') { load(); return; }
  var near = new IntersectionObserver(function(entries) {
    if (!entries.some(function(e) { return e.isIntersecting; })) return;
    near.disconnect();
    load();
  }, { rootMargin: '600px 0px' });
  near.observe(mapCanvas);
}

function setupMapWithData(data) {
  D = data;
  try {
    for (var i = 0; i < D.roads.length; i++) {
      D.roads[i].p = makePath(D.roads[i].geometry);
      D.roads[i].b = bounds(D.roads[i].geometry);
    }
    for (var i = 0; i < D.buildings.length; i++) {
      D.buildings[i].p = makePath(D.buildings[i].geometry);
      D.buildings[i].b = bounds(D.buildings[i].geometry);
    }
    for (var i = 0; i < D.areas.length; i++) {
      D.areas[i].p = makePath(D.areas[i].geometry);
      D.areas[i].b = bounds(D.areas[i].geometry);
    }
    if (D.historical) {
      for (var i = 0; i < D.historical.length; i++) {
        D.historical[i].p = makePath(D.historical[i].geometry);
        D.historical[i].b = bounds(D.historical[i].geometry);
      }
    }
    mapBoundaryPath = makePath(D.boundary);
    mapBufferPath = makePath(D.buffer);
    mapCampusBounds = bounds(D.boundary);
  } catch (e) {
    console.warn('Vector preprocessing error:', e);
  }

  resizeCampusMap();
  campusMapFitCampus(false);
  attachMapEvents();

  // Initial pin coordinate projection
  if (window.CampusGPS) {
    try {
      var p = CampusGPS.project(currentDraftCoords.lat, currentDraftCoords.lng, D.meta);
      mapCx = targetCx = p.x;
      mapCy = targetCy = p.y;
    } catch (e) {}
  }

  campusMapInstance = {
    flyTo: function(coords, zoomLevel) {
      flyMapToGps(coords[0], coords[1], zoomLevel ? zoomLevel / 10 : 1.8);
    },
    invalidateSize: function() {
      resizeCampusMap();
    }
  };
  window.campusMapInstance = campusMapInstance;

  // IntersectionObserver to pause loop when map is off-screen (prevents scroll lag!)
  if (typeof IntersectionObserver !== 'undefined') {
    var observer = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        isMapInViewport = entry.isIntersecting;
        if (isMapInViewport) {
          mapDirty = true;
          baseDirty = true;
          if (!mapRafId) mapRafId = requestAnimationFrame(campusMapLoop);
        }
      });
    }, { threshold: 0.05 });
    observer.observe(mapCanvas);
  } else {
    isMapInViewport = true;
  }

  renderMapExistingComplaints();
  mapRafId = requestAnimationFrame(campusMapLoop);
}

function resizeCampusMap() {
  if (!mapCanvas) return;
  var container = mapCanvas.parentElement;
  mapW = container ? container.clientWidth : 800;
  mapH = container ? container.clientHeight : 400;
  mapDpr = Math.min(window.devicePixelRatio || 1, 2);

  var pixelW = Math.round(mapW * mapDpr);
  var pixelH = Math.round(mapH * mapDpr);

  mapCanvas.width = pixelW;
  mapCanvas.height = pixelH;

  if (baseCanvas) {
    baseCanvas.width = pixelW;
    baseCanvas.height = pixelH;
  }

  if (D) {
    mapMinZ = Math.min((mapW - 30) / D.meta.width, (mapH - 30) / D.meta.height);
    mapZ = Math.max(mapZ, mapMinZ);
    targetZ = Math.max(targetZ, mapMinZ);
  }
  baseDirty = true;
  mapDirty = true;
}

export function campusMapFitCampus(all) {
  if (!D) return;
  var b = all ? [0, 0, D.meta.width, D.meta.height] : mapCampusBounds;
  targetCx = (b[0] + b[2]) / 2;
  targetCy = (b[1] + b[3]) / 2;
  targetZ = Math.min((mapW - 40) / (b[2] - b[0]), (mapH - 40) / (b[3] - b[1]));
  targetZ = Math.max(mapMinZ, Math.min(mapMaxZ, targetZ));
  mapVelocity = [0, 0];
  baseDirty = true;
  mapDirty = true;
}

export function campusMapZoom(factor) {
  campusMapZoomAt(factor, mapW / 2, mapH / 2);
}

function campusMapZoomAt(factor, sx, sy) {
  if (!Number.isFinite(factor) || factor <= 0) return;
  var w = mapWorld(sx, sy);
  targetZ = Math.max(mapMinZ, Math.min(mapMaxZ, targetZ * factor));
  mapZ = targetZ;
  mapCx = targetCx = w[0] - (sx - mapW / 2) / mapZ;
  mapCy = targetCy = w[1] - (sy - mapH / 2) / mapZ;
  mapClampView();
  baseDirty = true;
  mapDirty = true;
}

function mapClampView() {
  if (!D) return;
  targetCx = Math.max(-mapW / targetZ * 0.2, Math.min(D.meta.width + mapW / targetZ * 0.2, targetCx));
  targetCy = Math.max(-mapH / targetZ * 0.2, Math.min(D.meta.height + mapH / targetZ * 0.2, targetCy));
  mapCx = Math.max(-mapW / mapZ * 0.2, Math.min(D.meta.width + mapW / mapZ * 0.2, mapCx));
  mapCy = Math.max(-mapH / mapZ * 0.2, Math.min(D.meta.height + mapH / mapZ * 0.2, mapCy));
}

function flyMapToGps(lat, lon, zoomLevel) {
  if (!D || !window.CampusGPS) return;
  try {
    var p = CampusGPS.project(lat, lon, D.meta);
    flyMapToWorld(p.x, p.y, zoomLevel || 1.8);
  } catch (e) {
    console.warn('GPS flyTo error:', e);
  }
}

function flyMapToWorld(wx, wy, zoomLevel) {
  targetCx = wx;
  targetCy = wy;
  if (zoomLevel) targetZ = Math.max(mapMinZ, Math.min(mapMaxZ, zoomLevel));
  mapVelocity = [0, 0];
  baseDirty = true;
  mapDirty = true;
}

function campusMapToggleLabels() {
  mapShowLabels = !mapShowLabels;
  mapDirty = true;
}

function attachMapEvents() {
  if (!mapCanvas) return;

  window.addEventListener('resize', resizeCampusMap);

  // Smooth wheel zoom that only traps when cursor is intentionally zooming
  mapCanvas.addEventListener('wheel', function(e) {
    e.preventDefault();
    mapVelocity = [0, 0];
    var factor = Math.exp(-Math.max(-100, Math.min(100, e.deltaY)) * 0.0028);
    campusMapZoomAt(factor, e.offsetX, e.offsetY);
  }, { passive: false });

  mapCanvas.addEventListener('pointerdown', function(e) {
    mapCanvas.setPointerCapture(e.pointerId);
    mapPointers.set(e.pointerId, { x: e.offsetX, y: e.offsetY });
    mapVelocity = [0, 0];
    mapMoved = 0;
    mapLastMove = performance.now();
    if (mapPointers.size === 2) {
      var pts = Array.from(mapPointers.values());
      mapPinchState = {
        distance: Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y),
        x: (pts[0].x + pts[1].x) / 2,
        y: (pts[0].y + pts[1].y) / 2
      };
    }
  });

  mapCanvas.addEventListener('pointermove', function(e) {
    if (!mapPointers.has(e.pointerId)) return;
    var old = mapPointers.get(e.pointerId);
    var dx = e.offsetX - old.x;
    var dy = e.offsetY - old.y;
    mapPointers.set(e.pointerId, { x: e.offsetX, y: e.offsetY });
    mapMoved += Math.hypot(dx, dy);

    if (mapPointers.size === 2) {
      var pts = Array.from(mapPointers.values());
      var dist = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
      var midX = (pts[0].x + pts[1].x) / 2;
      var midY = (pts[0].y + pts[1].y) / 2;
      if (mapPinchState) {
        campusMapZoomAt(dist / Math.max(1, mapPinchState.distance), mapPinchState.x, mapPinchState.y);
        mapCx -= (midX - mapPinchState.x) / mapZ;
        mapCy -= (midY - mapPinchState.y) / mapZ;
      }
      mapPinchState = { distance: dist, x: midX, y: midY };
      mapVelocity = [0, 0];
    } else {
      mapCx -= dx / mapZ;
      mapCy -= dy / mapZ;
      targetCx = mapCx;
      targetCy = mapCy;
      var now = performance.now();
      var dt = Math.max(8, now - mapLastMove);
      mapVelocity = [dx * 16 / dt, dy * 16 / dt];
      mapLastMove = now;
    }
    mapClampView();
    baseDirty = true;
    mapDirty = true;
  });

  function onPointerEnd(e) {
    if (!mapPointers.has(e.pointerId)) return;
    var wasTap = mapMoved < 6 && mapPointers.size === 1;
    mapPointers.delete(e.pointerId);
    mapPinchState = null;

    if (wasTap) {
      mapVelocity = [0, 0];
      handleMapTap(e.offsetX, e.offsetY);
    }
  }

  mapCanvas.addEventListener('pointerup', onPointerEnd);
  mapCanvas.addEventListener('pointercancel', onPointerEnd);

  mapCanvas.addEventListener('dblclick', function(e) {
    mapVelocity = [0, 0];
    campusMapZoomAt(1.8, e.offsetX, e.offsetY);
  });
}

function handleMapTap(sx, sy) {
  // 1. Check if an active complaint marker was tapped
  for (var i = mapActiveComplaintHits.length - 1; i >= 0; i--) {
    var hit = mapActiveComplaintHits[i];
    if (Math.hypot(sx - hit.x, sy - hit.y) < 18) {
      showComplaintPopover(hit.complaint, hit.x, hit.y);
      return;
    }
  }

  // 2. Hide complaint popover if open
  var pop = document.getElementById('mapComplaintPopover');
  if (pop) pop.style.display = 'none';

  // 3. Check if a reviewed campus place was tapped
  for (var i = mapPlaceHits.length - 1; i >= 0; i--) {
    var phit = mapPlaceHits[i];
    if (Math.hypot(sx - phit.x, sy - phit.y) < 16) {
      var place = phit.p;
      setDraftPinLocation(place.lat, place.lon, place.name);
      flyMapToGps(place.lat, place.lon, 2.0);
      syncPlaceToForm(place);
      return;
    }
  }

  // 4. Tap on ground / building -> unproject to WGS84 GPS coordinate
  if (D && window.CampusGPS) {
    var w = mapWorld(sx, sy);
    try {
      var ll = CampusGPS.unproject(w[0], w[1], D.meta);
      var nearestPlace = findNearestPlace(ll.lat, ll.lon);
      var label = nearestPlace ? (nearestPlace.name + ' (Near Spot)') : ('Pinned Spot (' + ll.lat.toFixed(5) + '° N)');
      setDraftPinLocation(ll.lat, ll.lon, label);
      flyMapToWorld(w[0], w[1]);
      if (nearestPlace) syncPlaceToForm(nearestPlace);
    } catch (err) {
      console.warn('Map tap unproject error:', err);
    }
  }
}

function findNearestPlace(lat, lon) {
  if (!D || !D.places) return null;
  var best = null;
  var bestDist = Infinity;
  for (var i = 0; i < D.places.length; i++) {
    var p = D.places[i];
    var d = Math.hypot(lat - p.lat, lon - p.lon);
    if (d < bestDist && d < 0.0018) {
      bestDist = d;
      best = p;
    }
  }
  return best;
}

function syncPlaceToForm(place) {
  setReportPlace(place.name); // the complaint form is React (src/site/reportForm.ts)
}

function showComplaintPopover(c, sx, sy) {
  var pop = document.getElementById('mapComplaintPopover');
  if (!pop) return;
  var isUrgent = c.urgency === 'Urgent';
  pop.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d0ecc0;padding-bottom:5px;margin-bottom:6px;">' +
    '<strong style="color:var(--olive);font-size:12px;">' + escapeHtml(c.id) + '</strong>' +
    '<span style="font-size:10px;padding:2px 7px;border-radius:999px;background:' + (isUrgent ? '#fee2e2' : '#e0f5d0') + ';color:' + (isUrgent ? '#b91c1c' : 'var(--olive)') + ';font-weight:700;">' + (c.status || 'open').toUpperCase() + '</span>' +
    '</div>' +
    '<div style="font-size:12px;font-weight:600;color:#1a3010;margin-bottom:3px;">' + escapeHtml((c.title || c.desc || '').slice(0, 52)) + '...</div>' +
    '<div style="font-size:11px;color:#557048;margin-bottom:8px;">Location: ' + escapeHtml(c.location || 'Dibrugarh University') + '</div>' +
    '<button type="button" class="btn" style="height:26px;font-size:11px;padding:0 10px;width:100%;">View Live Status</button>';
  pop.querySelector('button').addEventListener('click', function () { openTrackerWithId(c.id); });
  pop.style.left = sx + 'px';
  pop.style.top = sy + 'px';
  pop.style.display = 'block';
}

export function setDraftPinLocation(lat, lng, label) {
  currentDraftCoords = { lat: Number(lat.toFixed(6)), lng: Number(lng.toFixed(6)) };
  if (label) currentDraftLocationLabel = label;

  var labelEl = document.getElementById('pinnedSpotLabel');
  if (labelEl) labelEl.textContent = currentDraftLocationLabel;
  var coordsEl = document.getElementById('pinnedCoordsText');
  if (coordsEl) coordsEl.textContent = currentDraftCoords.lat.toFixed(6) + '° N, ' + currentDraftCoords.lng.toFixed(6) + '° E';

  var pill = document.getElementById('mapStatusText');
  if (pill) pill.textContent = 'Pinned: ' + currentDraftLocationLabel.slice(0, 22);

  mapDirty = true;
}

function renderMapExistingComplaints() {
  mapDirty = true;
}

function resetCampusMap() {
  campusMapFitCampus(false);
}

// Draw the heavy static vector layers (buildings, trees, roads, areas) into an offscreen canvas
function drawBaseMap() {
  if (!baseCtx || !baseCanvas || !D) return;
  var ctx = baseCtx;

  ctx.setTransform(mapDpr, 0, 0, mapDpr, 0, 0);

  // Meadow background
  ctx.fillStyle = '#dde2bc';
  ctx.fillRect(0, 0, mapW, mapH);

  ctx.save();
  ctx.translate(mapW / 2, mapH / 2);
  ctx.scale(mapZ, mapZ);
  ctx.translate(-mapCx, -mapCy);

  // Buffer & boundary fills
  if (mapBufferPath) {
    ctx.fillStyle = '#d1ddb0';
    ctx.fill(mapBufferPath);
  }
  if (mapBoundaryPath) {
    ctx.fillStyle = '#dce6b8';
    ctx.fill(mapBoundaryPath);
  }

  // Areas
  var palette = { forest: '#79a16a', field: '#d8ca86', water: '#72bdca', pitch: '#b5cd81', land: '#d2dcb9' };
  for (var i = 0; i < D.areas.length; i++) {
    var a = D.areas[i];
    if (!isBBoxVisible(a.b)) continue;
    ctx.fillStyle = palette[a.kind] || '#d2dcb9';
    ctx.fill(a.p, 'evenodd');
    if (a.kind === 'water') {
      ctx.strokeStyle = '#4d9bab';
      ctx.lineWidth = Math.max(1, 0.8 / mapZ);
      ctx.stroke(a.p);
    }
  }

  // Trees from Map Kit (1,390 decorative trees)
  if (treeImg && treeImg.complete && treeImg.naturalWidth && D.trees) {
    ctx.imageSmoothingEnabled = false;
    for (var i = 0; i < D.trees.length; i++) {
      var t = D.trees[i];
      if (isBBoxVisible([t[0] - t[2], t[1] - t[2], t[0] + t[2], t[1] + t[2]])) {
        ctx.drawImage(treeImg, t[0] - t[2] / 2, t[1] - t[2] / 2, t[2], t[2]);
      }
    }
    ctx.imageSmoothingEnabled = true;
  }

  // Roads
  for (var i = 0; i < D.roads.length; i++) {
    var r = D.roads[i];
    if (!isBBoxVisible(r.b)) continue;
    var width = r.highway === 'primary' ? 12 : r.highway === 'track' ? 3 : r.highway === 'service' ? 4 : 5.5;
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';
    ctx.lineWidth = Math.max(width + 2, 2 / mapZ);
    ctx.strokeStyle = '#9c9e79';
    ctx.setLineDash([]);
    ctx.stroke(r.p);
    ctx.lineWidth = Math.max(width, 1.1 / mapZ);
    ctx.strokeStyle = r.highway === 'track' ? '#e8d8a6' : '#f7efd4';
    if (r.highway === 'track') ctx.setLineDash([4, 3]);
    ctx.stroke(r.p);
    ctx.setLineDash([]);
    if (r.highway === 'primary') {
      ctx.strokeStyle = '#cdbd8c';
      ctx.lineWidth = Math.max(0.8, 0.5 / mapZ);
      ctx.setLineDash([7, 5]);
      ctx.stroke(r.p);
      ctx.setLineDash([]);
    }
  }

  // 4,030 Vector Buildings
  for (var i = 0; i < D.buildings.length; i++) {
    var b = D.buildings[i];
    if (!isBBoxVisible(b.b)) continue;
    ctx.save();
    ctx.translate(1.8, 2.2);
    ctx.fillStyle = '#5c705940';
    ctx.fill(b.p);
    ctx.restore();

    ctx.fillStyle = b.source === 'OpenStreetMap' ? '#cf8c67' : '#e0aa83';
    ctx.strokeStyle = '#956548';
    ctx.lineWidth = Math.max(0.55, 0.45 / mapZ);
    ctx.fill(b.p, 'evenodd');
    ctx.stroke(b.p);
  }

  // Dashed Boundaries
  if (mapBufferPath) {
    ctx.lineWidth = 1.8 / mapZ;
    ctx.strokeStyle = '#4c94ad';
    ctx.setLineDash([7 / mapZ, 6 / mapZ]);
    ctx.stroke(mapBufferPath);
  }
  if (mapBoundaryPath) {
    ctx.lineWidth = 2.4 / mapZ;
    ctx.strokeStyle = '#d66643';
    ctx.setLineDash([7 / mapZ, 4 / mapZ]);
    ctx.stroke(mapBoundaryPath);
    ctx.setLineDash([]);
  }

  ctx.restore();
  baseDirty = false;
}

function campusMapLoop() {
  mapRafId = null;

  // If map is off-screen, completely pause rendering to keep 120fps page scrolling!
  if (!isMapInViewport) return;

  // Smooth camera interpolation
  var dx = targetCx - mapCx;
  var dy = targetCy - mapCy;
  var dz = targetZ - mapZ;
  if (Math.hypot(dx, dy) > 0.1 || Math.abs(dz) > 0.001) {
    mapCx += dx * 0.18;
    mapCy += dy * 0.18;
    mapZ += dz * 0.18;
    baseDirty = true;
    mapDirty = true;
  }

  // Inertia damping
  if (!mapPointers.size && Math.hypot(...mapVelocity) > 0.08) {
    mapCx -= mapVelocity[0] / mapZ;
    mapCy -= mapVelocity[1] / mapZ;
    targetCx = mapCx;
    targetCy = mapCy;
    mapVelocity = [mapVelocity[0] * 0.9, mapVelocity[1] * 0.9];
    mapClampView();
    baseDirty = true;
    mapDirty = true;
  }

  // Smooth radar phase
  mapRadarPhase = (mapRadarPhase + 0.035) % 1;
  mapDirty = true;

  if (mapDirty) {
    drawCampusMap();
    mapDirty = false;
  }

  mapRafId = requestAnimationFrame(campusMapLoop);
}

function drawCampusMap() {
  if (!mapCtx || !mapCanvas || !D) return;

  var ctx = mapCtx;

  // 1. Only re-render the heavy static 5,420 vector elements if the camera moved or zoomed
  if (baseDirty) {
    drawBaseMap();
  }

  // 2. Ultra-fast hardware-accelerated GPU blit (takes 0.05ms)
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.drawImage(baseCanvas, 0, 0);

  ctx.setTransform(mapDpr, 0, 0, mapDpr, 0, 0);

  // 3. Screen space renderings (Markers, Labels, Pins)
  mapPlaceHits = [];
  mapActiveComplaintHits = [];

  // Reviewed Places & Collision Labels
  if (mapShowLabels && D.places && window.CampusLabels) {
    ctx.font = '600 11px system-ui, -apple-system, sans-serif';
    ctx.textBaseline = 'middle';
    var visiblePlaces = [];
    for (var i = 0; i < D.places.length; i++) {
      var pl = D.places[i];
      var sc = mapScreen(...pl.geometry.coordinates);
      if (sc[0] >= -20 && sc[0] <= mapW + 20 && sc[1] >= -20 && sc[1] <= mapH + 20) {
        visiblePlaces.push({ id: pl.id, x: sc[0], y: sc[1], priority: pl.priority || 50, p: pl });
      }
    }

    var groups = CampusLabels.groups(visiblePlaces, 28);
    var occupiedBoxes = [];
    for (var i = 0; i < groups.length; i++) {
      var g = groups[i];
      var anchor = g.anchor;
      var p = anchor.p;
      var members = g.members;
      var isMulti = members.length > 1;

      ctx.fillStyle = p.campus ? '#255c43' : '#577d78';
      ctx.beginPath();
      ctx.arc(anchor.x, anchor.y, isMulti ? 8 : 3.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1.2;
      ctx.stroke();

      if (isMulti) {
        ctx.fillStyle = '#ffffff';
        ctx.textAlign = 'center';
        ctx.fillText(members.length, anchor.x, anchor.y);
        ctx.textAlign = 'left';
      }

      mapPlaceHits.push({ x: anchor.x, y: anchor.y, p: p });

      if (mapZ > 0.45) {
        var nameText = (mapZ >= 1.2 ? p.name : (p.display_name || p.name)) + (isMulti ? ' +' + (members.length - 1) : '');
        var tw = ctx.measureText(nameText).width;
        var bw = tw + 10;
        var bh = 18;
        var bx = anchor.x + 10;
        var by = anchor.y - bh / 2;

        if (bx + bw < mapW - 10 && by > 5 && by + bh < mapH - 10) {
          var overlaps = false;
          for (var j = 0; j < occupiedBoxes.length; j++) {
            var ob = occupiedBoxes[j];
            if (bx < ob.x + ob.w && bx + bw > ob.x && by < ob.y + ob.h && by + bh > ob.y) {
              overlaps = true;
              break;
            }
          }
          if (!overlaps) {
            occupiedBoxes.push({ x: bx, y: by, w: bw, h: bh });
            ctx.fillStyle = 'rgba(255, 255, 255, 0.92)';
            ctx.strokeStyle = '#c4dac0';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.roundRect(bx, by, bw, bh, 4);
            ctx.fill();
            ctx.stroke();
            ctx.fillStyle = '#174220';
            ctx.fillText(nameText, bx + 5, by + bh / 2);
          }
        }
      }
    }
  }

  // Active Complaints Pins
  if (typeof getComplaints === 'function' && window.CampusGPS) {
    var allComplaints = getComplaints();
    for (var i = 0; i < allComplaints.length; i++) {
      var c = allComplaints[i];
      var clat = c.lat;
      var clng = c.lng;
      if (!clat || !clng) {
        var locId = (c.aiAnalysis && c.aiAnalysis.location_id) || c.cat;
        if (locId && CAMPUS_LOCATION_COORDS[locId]) {
          clat = CAMPUS_LOCATION_COORDS[locId].lat;
          clng = CAMPUS_LOCATION_COORDS[locId].lng;
        }
      }
      if (clat && clng) {
        try {
          var cproj = CampusGPS.project(clat, clng, D.meta);
          var csc = mapScreen(cproj.x, cproj.y);
          if (csc[0] >= 0 && csc[0] <= mapW && csc[1] >= 0 && csc[1] <= mapH) {
            drawComplaintMarker(ctx, csc[0], csc[1], c);
            mapActiveComplaintHits.push({ x: csc[0], y: csc[1], complaint: c });
          }
        } catch (e) {}
      }
    }
  }

  // Draft Issue Location Pin (Selected / Camera Pin)
  if (window.CampusGPS && currentDraftCoords.lat && currentDraftCoords.lng) {
    try {
      var dproj = CampusGPS.project(currentDraftCoords.lat, currentDraftCoords.lng, D.meta);
      var dsc = mapScreen(dproj.x, dproj.y);
      drawDraftIssuePin(ctx, dsc[0], dsc[1]);
    } catch (e) {}
  }
}

function drawComplaintMarker(ctx, sx, sy, c) {
  var isUrgent = c.urgency === 'Urgent';
  var isHigh = c.urgency === 'High';
  var color = isUrgent ? '#dc2626' : isHigh ? '#d97706' : '#16a34a';

  ctx.fillStyle = 'rgba(0, 0, 0, 0.25)';
  ctx.beginPath();
  ctx.ellipse(sx, sy, 6, 2.5, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = color;
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(sx, sy - 8, 7.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();

  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(sx, sy - 8, 2.5, 0, Math.PI * 2);
  ctx.fill();
}

function drawDraftIssuePin(ctx, sx, sy) {
  var radarRadius = 10 + mapRadarPhase * 28;
  var radarAlpha = (1 - mapRadarPhase) * 0.45;
  ctx.save();
  ctx.strokeStyle = 'rgba(0, 54, 255, ' + radarAlpha + ')';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(sx, sy, radarRadius, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();

  ctx.fillStyle = 'rgba(19, 78, 44, 0.35)';
  ctx.beginPath();
  ctx.ellipse(sx, sy + 1, 11, 4.5, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = '#0f172a';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(sx, sy);
  ctx.lineTo(sx, sy - 22);
  ctx.stroke();
  ctx.strokeStyle = '#cbd5e1';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(sx - 0.5, sy - 2);
  ctx.lineTo(sx - 0.5, sy - 20);
  ctx.stroke();

  var grad = ctx.createRadialGradient(sx - 3, sy - 31, 1, sx, sy - 29, 11);
  grad.addColorStop(0, '#93c5fd');
  grad.addColorStop(0.35, '#2563eb');
  grad.addColorStop(0.8, '#1e3a8a');
  grad.addColorStop(1, '#091e42');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(sx, sy - 28, 10, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(sx - 3, sy - 31, 2.5, 0, Math.PI * 2);
  ctx.fill();

  ctx.font = '700 10.5px system-ui, -apple-system, sans-serif';
  var tagText =  (currentDraftLocationLabel.length > 24 ? currentDraftLocationLabel.slice(0, 22) + '...' : currentDraftLocationLabel);
  var tw = ctx.measureText(tagText).width;
  var bw = tw + 14;
  var bh = 22;
  var bx = sx - bw / 2;
  var by = sy - 54;

  ctx.fillStyle = '#134E2C';
  ctx.strokeStyle = '#B5F800';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.roundRect(bx, by, bw, bh, 5);
  ctx.fill();
  ctx.stroke();

  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(tagText, sx, by + bh / 2);
  ctx.textAlign = 'left';
}

function locateUserGps() {
  var pill = document.getElementById('mapStatusText');
  if (pill) pill.textContent = 'Acquiring GPS fix...';

  if (typeof navigator !== 'undefined' && navigator.geolocation) {
    navigator.geolocation.getCurrentPosition(
      function(pos) {
        var lat = pos.coords.latitude;
        var lon = pos.coords.longitude;
        var acc = Math.round(pos.coords.accuracy || 10);

        if (D && window.CampusGPS) {
          try {
            var p = CampusGPS.project(lat, lon, D.meta);
            if (CampusGPS.inExtent(p, D.meta)) {
              setDraftPinLocation(lat, lon, 'Device GPS Spot (±' + acc + 'm)');
              flyMapToWorld(p.x, p.y, 2.0);
              if (pill) pill.textContent = 'GPS Located (±' + acc + 'm)';
              return;
            }
          } catch (e) {}
        }

        fallbackLandmarkPin('GPS Active (Campus Centered)');
      },
      function(err) {
        fallbackLandmarkPin('Campus Landmark');
      },
      { enableHighAccuracy: true, timeout: 6000, maximumAge: 0 }
    );
  } else {
    fallbackLandmarkPin('Campus Landmark');
  }
}

function fallbackLandmarkPin(reason) {
  var activeLoc = document.getElementById('fLocation') ? document.getElementById('fLocation').value : '';
  var spot = (CAMPUS_LOCATION_COORDS && CAMPUS_LOCATION_COORDS[activeLoc]) || (CAMPUS_LOCATION_COORDS && CAMPUS_LOCATION_COORDS.du_hostel_1);
  if (spot) {
    setDraftPinLocation(spot.lat, spot.lng, spot.name);
    flyMapToGps(spot.lat, spot.lng, 1.8);
    var pill = document.getElementById('mapStatusText');
    if (pill) pill.textContent = spot.name.slice(0, 22);
  }
}

/** Moves the draft pin to a landmark named in the complaint text. Returns false for unknown landmarks. */
export function focusMapOnLandmark(locationId) {
  var landmark = CAMPUS_LOCATION_COORDS[locationId];
  if (!landmark) return false;
  setDraftPinLocation(landmark.lat, landmark.lng, landmark.name);
  if (campusMapInstance && !campusMapInstance._animating) {
    campusMapInstance.flyTo([landmark.lat, landmark.lng], 17, { duration: 1.2 });
  }
  return true;
}
